-- Create rate_limit_logs table\nCREATE TABLE rate_limit_logs (\n    id SERIAL PRIMARY KEY,\n    user_id UUID NOT NULL,\n    request_timestamp TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,\n    request_path TEXT NOT NULL,\n    response_status INT NOT NULL,\n    ip_address INET NOT NULL\n);\n\n-- Create indexes\nCREATE INDEX idx_user_id ON rate_limit_logs (user_id);\nCREATE INDEX idx_request_timestamp ON rate_limit_logs (request_timestamp);\n\n-- Enable Row-Level Security\nALTER TABLE rate_limit_logs ENABLE ROW LEVEL SECURITY;\n\n-- Create policies\nCREATE POLICY select_policy ON rate_limit_logs\n    FOR SELECT\n    USING (user_id = auth.uid());\n\nCREATE POLICY insert_policy ON rate_limit_logs\n    FOR INSERT\n    WITH CHECK (user_id = auth.uid());\n\n-- Function for automated cleanup\nCREATE OR REPLACE FUNCTION cleanup_rate_limit_logs() RETURNS VOID AS $$\nBEGIN\n    DELETE FROM rate_limit_logs\n    WHERE request_timestamp < NOW() - INTERVAL '30 days';\nEND;\n$$ LANGUAGE plpgsql;\n\n-- Schedule the cleanup function (e.g., to run daily)\nSELECT cron.schedule('0 0 * * *', 'SELECT cleanup_rate_limit_logs()');\n